using Xunit;
using Moq;

public class SymptomTest
{
    private readonly ISymptomService _symptomService;

    public SymptomTest()
    {
        _symptomService = new Mock<ISymptomService>().Object;
    }

    [Fact]
    public void TestAddSymptom()
    {
        var symptom = new Symptom { Name = "Headache", Description = "Constant pain in the head" };

        var result = _symptomService.AddSymptom(symptom);

        Assert.Equal(symptom, result);
    }

    [Fact]
    public void TestUpdateSymptomDescription()
    {
        var symptom = new Symptom { Name = "Headache", Description = "Constant pain in the head" };

        _symptomService.AddSymptom(symptom);

        symptom.Description = "New description";

        _symptomService.UpdateSymptom(symptom);

        Assert.Equal("New description", symptom.Description);
    }

    [Fact]
    public void TestDeleteSymptom()
    {
        var symptom = new Symptom { Name = "Headache", Description = "Constant pain in the head" };

        _symptomService.AddSymptom(symptom);

        Assert.Throws<Exception>(() => _symptomService.DeleteSymptom(symptom.Id));
    }

    [Fact]
    public void TestDeleteSymptom_SymptomUsed()
    {
        var symptom = new Symptom { Name = "Headache", Description = "Constant pain in the head" };

        _symptomService.AddSymptom(symptom);

        // Simulate symptom being used in a consultation request
        _symptomService.AddConsultationRequest(new ConsultationRequest { SymptomId = symptom.Id });

        Assert.Throws<Exception>(() => _symptomService.DeleteSymptom(symptom.Id));
    }
}

using Xunit;

public class SymptomTest
{
    private readonly ISymptomService _symptomService;

    public SymptomTest(ISymptomService symptomService)
    {
        _symptomService = symptomService;
    }

    [Fact]
    public void AddSymptom_ValidInput_ReturnsCreatedSymptom()
    {
        // Arrange
        var symptom = new Symptom { Name = "Headache", Description = "Constant pain in the head" };

        // Act
        var createdSymptom = _symptomService.AddSymptom(symptom);

        // Assert
        Assert.Equal(symptom.Name, createdSymptom.Name);
        Assert.Equal(symptom.Description, createdSymptom.Description);
    }

    [Fact]
    public void AddSymptom_InvalidInput_ThrowsArgumentException()
    {
        // Arrange
        var symptom = new Symptom { Description = "New description" };

        // Act & Assert
        Assert.Throws<ArgumentException>(() => _symptomService.AddSymptom(symptom));
    }

    [Fact]
    public void UpdateSymptom_ValidInput_ReturnsUpdatedSymptom()
    {
        // Arrange
        var symptom = new Symptom { Name = "Headache", Description = "Constant pain in the head" };
        var updatedSymptom = new Symptom { Name = "Headache", Description = "New description" };

        // Act
        var updated = _symptomService.UpdateSymptom(symptom.Id, updatedSymptom);

        // Assert
        Assert.True(updated);
        Assert.Equal(updatedSymptom.Description, _symptomService.GetSymptom(symptom.Id).Description);
    }

    [Fact]
    public void DeleteSymptom_WithNoConsultationRequests_ReturnsTrue()
    {
        // Arrange
        var symptom = new Symptom { Name = "Headache", Description = "Constant pain in the head" };

        // Act
        var deleted = _symptomService.DeleteSymptom(symptom.Id);

        // Assert
        Assert.True(deleted);
        Assert.Throws<SymptomNotFoundException>(() => _symptomService.GetSymptom(symptom.Id));
    }

    [Fact]
    public void DeleteSymptom_WithConsultationRequests_ThrowsSymptomInUseException()
    {
        // Arrange
        var symptom = new Symptom { Name = "Headache", Description = "Constant pain in the head" };
        _symptomService.AddSymptom(symptom);
        // Create a ConsultationRequest with the symptom
        // ...

        // Act & Assert
        Assert.Throws<SymptomInUseException>(() => _symptomService.DeleteSymptom(symptom.Id));
    }
}
